--
-- Table structure for table `organizations`
--

DROP TABLE IF EXISTS `organizations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `organizations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `organization_code` varchar(50) NOT NULL,
  `company_name` varchar(200) NOT NULL,
  `legal_name` varchar(250) DEFAULT NULL,
  `owner_name` varchar(150) NOT NULL,
  `email` varchar(150) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `address` text DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `state` varchar(100) DEFAULT NULL,
  `country` varchar(100) DEFAULT 'India',
  `timezone` varchar(100) DEFAULT 'Asia/Kolkata',
  `currency` varchar(10) DEFAULT 'INR',
  `logo` varchar(255) DEFAULT NULL,
  `plan_id` int(11) DEFAULT NULL,
  `custom_price_monthly` decimal(10,2) DEFAULT NULL,
  `custom_price_yearly` decimal(10,2) DEFAULT NULL,
  `custom_setup_fee` decimal(10,2) DEFAULT NULL,
  `custom_limits_json` text DEFAULT NULL,
  `subscription_end_date` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `custom_plan_id` int(11) DEFAULT NULL,
  `subscription_status` enum('trial','active','suspended','cancelled') DEFAULT 'trial',
  `trial_start` date DEFAULT NULL,
  `trial_end` date DEFAULT NULL,
  `custom_domain` varchar(200) DEFAULT NULL,
  `branding_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`branding_json`)),
  `referral_code` varchar(50) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `organization_code` (`organization_code`),
  UNIQUE KEY `uk_org_ref_code` (`referral_code`),
  KEY `plan_id` (`plan_id`),
  KEY `idx_org_code` (`organization_code`),
