DROP TABLE IF EXISTS `plans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `plans` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `plan_code` varchar(50) NOT NULL,
  `plan_slug` varchar(100) DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `price_monthly` decimal(10,2) NOT NULL DEFAULT 0.00,
  `price_yearly` decimal(10,2) NOT NULL DEFAULT 0.00,
  `setup_fee` decimal(10,2) NOT NULL DEFAULT 0.00,
  `currency` varchar(10) DEFAULT 'INR',
  `billing_type` varchar(50) DEFAULT 'flat',
  `display_order` int(11) DEFAULT 0,
  `is_recommended` tinyint(1) DEFAULT 0,
  `is_custom` tinyint(1) NOT NULL DEFAULT 0,
  `cta_text` varchar(100) DEFAULT 'Start Free Trial',
  `cta_action` varchar(100) DEFAULT 'whatsapp',
  `trial_enabled` tinyint(1) DEFAULT 1,
  `trial_days` int(11) DEFAULT 14,
  `yearly_discount_pct` int(11) DEFAULT 15,
  `max_buildings` int(11) NOT NULL DEFAULT 1,
  `max_rooms` int(11) NOT NULL DEFAULT -1,
  `max_beds` int(11) NOT NULL DEFAULT 100,
  `max_staff` int(11) NOT NULL DEFAULT 3,
  `max_residents` int(11) NOT NULL DEFAULT 100,
  `max_storage_gb` int(11) NOT NULL DEFAULT -1,
  `max_api_requests` int(11) NOT NULL DEFAULT -1,
  `features_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`features_json`)),
  `status` enum('active','archived') DEFAULT 'active',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `plan_code` (`plan_code`),
  UNIQUE KEY `plan_slug` (`plan_slug`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
